(function () {
  // ── shared helpers (SVG, tweening) ─────────────────────────────────────────
  var NS = "http://www.w3.org/2000/svg";
  var svg = document.getElementById("scene");
  var labelEl = document.getElementById("step-label");
  var captionEl = document.getElementById("caption");

  function el(name, attrs, parent) {
    var node = document.createElementNS(NS, name);
    for (var key in attrs) node.setAttribute(key, attrs[key]);
    if (parent) parent.appendChild(node);
    return node;
  }
  function txt(parent, x, y, cls, str, anchor) {
    var t = el("text", { x: x, y: y, class: cls }, parent);
    if (anchor) t.setAttribute("text-anchor", anchor);
    t.textContent = str;
    return t;
  }
  function show(node, on) {
    node.setAttribute("opacity", on ? "1" : "0");
  }
  function place(node, x, y) {
    node.style.transform = "translate(" + x + "px," + y + "px)";
  }
  function setLine(node, x1, y1, x2, y2) {
    node.setAttribute("x1", x1);
    node.setAttribute("y1", y1);
    node.setAttribute("x2", x2);
    node.setAttribute("y2", y2);
  }
  function lerp(a, b, e) {
    return a + (b - a) * e;
  }
  function round1(v) {
    return (Math.round(v * 10) / 10).toFixed(1);
  }

  // Eased animation. fn(e) is called with e from 0 to 1. Without
  // requestAnimationFrame (or with ms = 0) it jumps straight to fn(1).
  var animTokens = {};
  function anim(key, ms, fn) {
    var token = (animTokens[key] || 0) + 1;
    animTokens[key] = token;
    if (typeof requestAnimationFrame !== "function" || ms <= 0) {
      fn(1);
      return;
    }
    var start = null;
    function frame(now) {
      if (animTokens[key] !== token) return;
      if (start === null) start = now;
      var p = Math.min(1, (now - start) / ms);
      var e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
      fn(e);
      if (p < 1) requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  }

  // Arrowheads, one marker per colour.
  var COLORS = { g: "#1DB584", y: "#E2B44A", p: "#F472B6", b: "#38BDF8", w: "#c9dccf", r: "#F87171" };
  var defs = el("defs", {}, svg);
  Object.keys(COLORS).forEach(function (k) {
    var m = el("marker", { id: "ah-" + k, viewBox: "0 0 10 10", refX: 9, refY: 5, markerUnits: "userSpaceOnUse", markerWidth: 13, markerHeight: 13, orient: "auto" }, defs);
    el("path", { d: "M0 0 L10 5 L0 10 Z", fill: COLORS[k] }, m);
  });
  function arrow(parent, colorKey, width) {
    return el("line", { x1: 0, y1: 0, x2: 0, y2: 0, stroke: COLORS[colorKey], "stroke-width": width || 3, "marker-end": "url(#ah-" + colorKey + ")", "stroke-linecap": "round" }, parent);
  }
  function polygon(parent, cls) {
    return el("polygon", { points: "", class: cls }, parent);
  }
  function setPoly(node, pts) {
    node.setAttribute("points", pts.map(function (p) { return p[0].toFixed(1) + "," + p[1].toFixed(1); }).join(" "));
  }
  function lerpPts(a, b, e) {
    return a.map(function (p, i) { return [lerp(p[0], b[i][0], e), lerp(p[1], b[i][1], e)]; });
  }
  // Maps maths coordinates (x right, y up) to screen pixels.
  function makePlane(cx, cy, s) {
    return {
      x: function (v) { return cx + s * v; },
      y: function (v) { return cy - s * v; },
      pt: function (p) { return [cx + s * p[0], cy - s * p[1]]; },
      s: s, cx: cx, cy: cy
    };
  }
  function axes(parent, plane, xr, yr) {
    el("line", { x1: plane.x(-xr), y1: plane.y(0), x2: plane.x(xr), y2: plane.y(0), class: "axis" }, parent);
    el("line", { x1: plane.x(0), y1: plane.y(-yr), x2: plane.x(0), y2: plane.y(yr), class: "axis" }, parent);
  }

  // ── Module 3 helpers: graphs, curves, contour plane ───────────────────────
  // makeGraph maps maths values to pixels with separate x and y scales.
  function makeGraph(ox, oy, sx, sy) {
    return {
      ox: ox, oy: oy, sx: sx, sy: sy,
      x: function (v) { return ox + sx * v; },
      y: function (v) { return oy - sy * v; }
    };
  }
  function curveD(g, f, a, b, n) {
    var d = "";
    for (var i = 0; i <= n; i++) {
      var v = a + ((b - a) * i) / n;
      d += (i ? " L " : "M ") + g.x(v).toFixed(1) + " " + g.y(f(v)).toFixed(1);
    }
    return d;
  }
  function setD(node, d) {
    node.setAttribute("d", d);
  }
  function fmt(v, n) {
    return (Math.round(v * 100000) / 100000).toFixed(n === undefined ? 1 : n);
  }
  function drawAxes(parent, g, xmax, ymax, xticks, yticks) {
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(xmax), y2: g.y(0), class: "axis" }, parent);
    el("line", { x1: g.x(0), y1: g.y(0), x2: g.x(0), y2: g.y(ymax), class: "axis" }, parent);
    (xticks || []).forEach(function (t) { txt(parent, g.x(t), g.y(0) + 15, "tick", String(t), "middle"); });
    (yticks || []).forEach(function (t) { txt(parent, g.x(0) - 7, g.y(t) + 4, "tick", String(t), "end"); });
  }
  function card(parent, x, y, w, h, cls) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: 10, class: cls || "fillG" }, parent);
  }
  function ring(parent, cx, cy, rx, ry, cls) {
    return el("ellipse", { cx: cx, cy: cy, rx: rx, ry: ry, fill: "none", class: cls || "contour" }, parent);
  }
  function clipTo(id, x, y, w, h) {
    var c = el("clipPath", { id: id }, defs);
    el("rect", { x: x, y: y, width: w, height: h }, c);
  }

  // ── Module 4 helpers: seeded randomness, small shapes ─────────────────────
  function mulberry(seed) {
    var a = seed;
    return function () {
      a |= 0; a = (a + 0x6D2B79F5) | 0;
      var t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  function gaussSource(rand) {
    return function () {
      var u = 1 - rand(), v = rand();
      return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
    };
  }
  function box(parent, x, y, w, h, fill, stroke, r) {
    return el("rect", { x: x, y: y, width: w, height: h, rx: r === undefined ? 6 : r, fill: fill, stroke: stroke || "none", "stroke-width": 2 }, parent);
  }
  function setBox(node, x, y, w, h) {
    node.setAttribute("x", x); node.setAttribute("y", y); node.setAttribute("width", Math.max(0, w)); node.setAttribute("height", Math.max(0, h));
  }
  function vis(list, on) {
    list.forEach(function (n) { show(n, on); });
  }

  var EXPLAIN = {"scatter":{"h":"WHAT YOU ARE LOOKING AT","t":"Each point is one house: **size across, price up**. We want one number that says whether the two variables **move together**, and in which direction."},"positive":{"h":"POSITIVE: THEY RISE TOGETHER","t":"Bigger houses cost more: as size grows, price grows. The points climb from lower left to upper right. This is **positive covariance**."},"negative":{"h":"NEGATIVE: ONE UP, THE OTHER DOWN","t":"Now imagine price falls as size grows (say, size versus distance to the city). The points slide from upper left to lower right. This is **negative covariance**."},"near-zero":{"h":"NEAR ZERO: NO STRAIGHT-LINE TREND","t":"Here the points show **no consistent upward or downward trend**. Knowing the size tells you nothing about which side of the average the price is on. Covariance is about zero."},"covariance":{"h":"HOW COVARIANCE IS COMPUTED","t":"Mark the means (the cross). Each point makes a **rectangle**: its distance from the mean in x times its distance in y. Green rectangles (same side of both means) count positive, red negative. Covariance is their average: **(6+2+0+1+8)/5 = 3.4**."},"rescale":{"h":"COVARIANCE DEPENDS ON THE UNITS","t":"Measure size in units **ten times larger**. The points have exactly the same shape, yet covariance jumps from **3.4 to 34**. A raw covariance is hard to compare across variables."},"correlation":{"h":"CORRELATION REMOVES THE UNITS","t":"Divide by both standard deviations: **Corr = Cov / (σx × σy) = 3.4 / (√2 × √6) ≈ 0.98.** Correlation is always between **−1 and +1**: +1 a perfect rising line, −1 a perfect falling line, 0 no straight-line trend."},"zero-not-independence":{"h":"ZERO CORRELATION IS NOT INDEPENDENCE","t":"These points follow **y = (x − 3)²**: y is completely determined by x. Yet the left and right halves cancel, so covariance and correlation are exactly **0**. Correlation only detects **straight-line** relationships."},"ml-connection":{"h":"TAKEAWAY","t":"**Highly correlated features are redundant.** Collect all the variances and covariances into a **covariance matrix**: it is the key ingredient of PCA and of the multivariate normal in the next checkpoint."}};
  // ── scene ──
  var steps = [
    { id: "scatter", label: "Five houses as points", caption: "Each point is one house: size across, price up. We want one number that says whether the two variables move together, and in which direction." },
    { id: "positive", label: "Positive: they rise together", caption: "Bigger houses cost more: as size grows, price grows. The points climb from lower left to upper right. This is positive covariance." },
    { id: "negative", label: "Negative: one up, the other down", caption: "Now imagine price falls as size grows (say, size versus distance to the city). The points slide from upper left to lower right. This is negative covariance." },
    { id: "near-zero", label: "Near zero: no straight-line trend", caption: "Here the points show no consistent upward or downward trend. Knowing the size tells you nothing about which side of the average the price is on. Covariance is about zero." },
    { id: "covariance", label: "How covariance is computed", caption: "Mark the means (the cross). Each point makes a rectangle: its distance from the mean in x times its distance in y. Green rectangles (same side of both means) count positive, red negative. Covariance is their average: (6+2+0+1+8)/5 = 3.4." },
    { id: "rescale", label: "Covariance depends on the units", caption: "Measure size in units ten times larger. The points have exactly the same shape, yet covariance jumps from 3.4 to 34. A raw covariance is hard to compare across variables." },
    { id: "correlation", label: "Correlation removes the units", caption: "Divide by both standard deviations: Corr = Cov / (σx × σy) = 3.4 / (√2 × √6) ≈ 0.98. Correlation is always between −1 and +1: +1 is a perfect rising line, −1 a perfect falling line, 0 no straight-line trend." },
    { id: "zero-not-independence", label: "Zero correlation is not independence", caption: "These points follow y = (x − 3)²: y is completely determined by x. Yet the left and right halves cancel, so covariance and correlation are exactly 0. Correlation only detects straight-line relationships." },
    { id: "ml-connection", label: "Why ML cares", caption: "Highly correlated features are redundant. Collect all the variances and covariances into a covariance matrix: it is the key ingredient of PCA and of the multivariate normal in the next checkpoint." }
  ];

  var XS = [1, 2, 3, 4, 5];
  var DATA = {
    pos: [2, 3, 5, 6, 9],
    neg: [9, 6, 5, 3, 2],
    flat: [4, 6, 3, 6, 4],
    para: [4, 1, 0, 1, 4]
  };
  function mean(v) { var s = 0; v.forEach(function (a) { s += a; }); return s / v.length; }
  function cov(x, y) { var mx = mean(x), my = mean(y), s = 0; for (var i = 0; i < x.length; i++) s += (x[i] - mx) * (y[i] - my); return s / x.length; }
  function corr(x, y) { return cov(x, y) / Math.sqrt(cov(x, x) * cov(y, y)); }

  var PXf = function (x) { return 60 + 56 * x; };
  var PYf = function (y) { return 304 - 26 * y; };
  var L = 60, R = 360, T = 40, B = 304;

  // Quadrants and axes.
  var quadG = el("g", {}, svg);
  var quads = [
    box(quadG, 0, 0, 0, 0, "rgba(29,181,132,0.14)", "none", 0),
    box(quadG, 0, 0, 0, 0, "rgba(29,181,132,0.14)", "none", 0),
    box(quadG, 0, 0, 0, 0, "rgba(248,113,113,0.14)", "none", 0),
    box(quadG, 0, 0, 0, 0, "rgba(248,113,113,0.14)", "none", 0)
  ];
  var axG = el("g", {}, svg);
  el("line", { x1: L, y1: B, x2: R + 10, y2: B, class: "axis" }, axG);
  el("line", { x1: L, y1: B, x2: L, y2: T - 8, class: "axis" }, axG);
  var xTicks = XS.map(function (x) { return txt(axG, PXf(x), B + 16, "tick", String(x), "middle"); });
  txt(axG, R + 10, B + 32, "note", "size", "end");
  txt(axG, L + 6, T - 12, "note", "price", "start");

  var meanG = el("g", {}, svg);
  var mLineV = el("line", { stroke: "#e2b44a", "stroke-width": 2, "stroke-dasharray": "6 4" }, meanG);
  var mLineH = el("line", { stroke: "#e2b44a", "stroke-width": 2, "stroke-dasharray": "6 4" }, meanG);
  var mLbl = txt(meanG, 0, 0, "lbl lbl-y", "means", "start");

  var prodG = el("g", {}, svg);
  var prods = XS.map(function () { return box(prodG, 0, 0, 0, 0, "rgba(29,181,132,0.5)", "none", 0); });

  var curveG = el("g", {}, svg);
  var curvePath = el("path", { fill: "none", stroke: "#f472b6", "stroke-width": 2.5, "stroke-dasharray": "6 4" }, curveG);
  var dCurve = "";
  for (var cx = 0.6; cx <= 5.41; cx += 0.2) dCurve += (dCurve ? " L " : "M ") + PXf(cx).toFixed(1) + " " + PYf((cx - 3) * (cx - 3)).toFixed(1);
  setD(curvePath, dCurve);

  var trendG = el("g", {}, svg);
  var trendPos = arrow(trendG, "g", 5), trendNeg = arrow(trendG, "r", 5), trendFlat = arrow(trendG, "w", 5);
  var trendLbl = txt(trendG, 0, 0, "lbl lbl-g", "", "start");

  var pts = XS.map(function () { return el("circle", { r: 8, fill: "#38bdf8", stroke: "#071510", "stroke-width": 2 }, svg); });
  var cur = DATA.pos.slice();
  function drawPoints(ys) {
    cur = ys;
    for (var i = 0; i < 5; i++) { pts[i].setAttribute("cx", PXf(XS[i])); pts[i].setAttribute("cy", PYf(ys[i])); }
  }
  function morph(target, ms) {
    var from = cur.slice();
    anim("pts", ms, function (e) { drawPoints(from.map(function (v, i) { return lerp(v, target[i], e); })); });
  }
  function drawMeanAndQuads(ys) {
    var mx = mean(XS), my = mean(ys);
    var cxp = PXf(mx), cyp = PYf(my);
    setLine(mLineV, cxp, T - 6, cxp, B);
    setLine(mLineH, L, cyp, R + 6, cyp);
    mLbl.setAttribute("x", cxp + 8); mLbl.setAttribute("y", T + 6);
    setBox(quads[0], cxp, T - 6, R + 6 - cxp, cyp - (T - 6));      // upper right: +
    setBox(quads[1], L, cyp, cxp - L, B - cyp);                      // lower left: +
    setBox(quads[2], L, T - 6, cxp - L, cyp - (T - 6));              // upper left: -
    setBox(quads[3], cxp, cyp, R + 6 - cxp, B - cyp);                // lower right: -
  }
  function drawProducts(ys) {
    var mx = mean(XS), my = mean(ys);
    for (var i = 0; i < 5; i++) {
      var dx = XS[i] - mx, dy = ys[i] - my, p = dx * dy;
      var x1 = PXf(mx), y1 = PYf(my), x2 = PXf(XS[i]), y2 = PYf(ys[i]);
      setBox(prods[i], Math.min(x1, x2), Math.min(y1, y2), Math.abs(x2 - x1), Math.abs(y2 - y1));
      prods[i].setAttribute("fill", p > 0 ? "rgba(29,181,132,0.55)" : "rgba(248,113,113,0.55)");
      prods[i].setAttribute("opacity", p === 0 ? "0" : "1");
    }
  }

  // Scale bar for correlation.
  var scaleG = el("g", {}, svg);
  var SX = function (c) { return 90 + (c + 1) * 120; };
  el("line", { x1: SX(-1), y1: 190, x2: SX(1), y2: 190, stroke: "#c9dccf", "stroke-width": 3 }, scaleG);
  [-1, 0, 1].forEach(function (c) {
    el("line", { x1: SX(c), y1: 182, x2: SX(c), y2: 198, stroke: "#c9dccf", "stroke-width": 3 }, scaleG);
    txt(scaleG, SX(c), 220, "big", (c > 0 ? "+" : "") + c, "middle");
  });
  txt(scaleG, SX(-1), 242, "note", "falling line", "middle");
  txt(scaleG, SX(0), 242, "note", "no straight-line trend", "middle");
  txt(scaleG, SX(1), 242, "note", "rising line", "middle");
  [[corr(XS, DATA.neg), "#f87171", "falling data"], [corr(XS, DATA.flat), "#c9dccf", "unrelated"], [corr(XS, DATA.pos), "#1db584", "rising data"]].forEach(function (m, i) {
    el("circle", { cx: SX(m[0]), cy: 190, r: 9, fill: m[1], stroke: "#071510", "stroke-width": 2 }, scaleG);
    txt(scaleG, SX(m[0]), i === 1 ? 160 : 160 - (i === 0 ? 0 : 0), "lbl", fmt(m[0], 2), "middle");
  });
  txt(scaleG, 320, 130, "mono", "Corr = Cov / (σx × σy) = 3.4 / √12 ≈ 0.98", "middle");
  txt(scaleG, 320, 290, "lbl lbl-y", "always between −1 and +1, whatever the units", "middle");

  var mlG = el("g", {}, svg);
  txt(mlG, 320, 40, "lbl lbl-y", "the covariance matrix of (size, price)", "middle");
  box(mlG, 150, 60, 150, 60, "rgba(56,189,248,0.2)", "#38bdf8", 8);
  box(mlG, 300, 60, 150, 60, "rgba(29,181,132,0.3)", "#1db584", 8);
  box(mlG, 150, 120, 150, 60, "rgba(29,181,132,0.3)", "#1db584", 8);
  box(mlG, 300, 120, 150, 60, "rgba(56,189,248,0.2)", "#38bdf8", 8);
  txt(mlG, 225, 98, "big", "2.0", "middle"); txt(mlG, 225, 114, "note", "var(size)", "middle");
  txt(mlG, 375, 98, "big", "3.4", "middle"); txt(mlG, 375, 114, "note", "cov(size, price)", "middle");
